import { test, expect } from '@playwright/test';

test.describe('ZIP Code Auto-Formatting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should format ZIP code correctly on input', async ({ page }) => {
    const zipCodeInput = page.getByLabel('ZIP Code');

    await zipCodeInput.fill('123456789');
    await expect(zipCodeInput).toHaveValue('12345-6789');
  });

  test('should not format invalid ZIP code', async ({ page }) => {
    const zipCodeInput = page.getByLabel('ZIP Code');

    await zipCodeInput.fill('1234');
    await expect(zipCodeInput).toHaveValue('1234');
  });
});
